-- AI Usage Note
-- Generated by Claude (Claude Code): this migration.
-- How it was verified: applied with prisma migrate reset twice in a row; connected as each role to check what is allowed and what is refused; a table created after the migration was readable by nearby_main.
-- Reviewed by: Vlad-Re
--
-- Database roles from docs/architecture/mechanisms/database-access.md. The roles are created without a
-- password, so nobody can sign in as them until `npm run db:set-passwords` sets one.
-- ALTER DEFAULT PRIVILEGES applies to tables created later by the role that runs this migration.

DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'nearby_main') THEN
        CREATE ROLE nearby_main LOGIN;
    END IF;
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'nearby_import') THEN
        CREATE ROLE nearby_import LOGIN;
    END IF;
END
$$;

-- nearby_main: read and write all application tables, no schema changes.
GRANT USAGE ON SCHEMA public TO nearby_main;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO nearby_main;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO nearby_main;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO nearby_main;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO nearby_main;
REVOKE ALL ON TABLE "_prisma_migrations" FROM nearby_main;

-- nearby_import: write imported events and venues and the import log, read categories.
GRANT USAGE ON SCHEMA public TO nearby_import;
GRANT SELECT, INSERT, UPDATE ON "events", "venues", "import_runs", "skipped_records" TO nearby_import;
GRANT SELECT ON "categories" TO nearby_import;
